                else if (r.type == 2) { Flag(e); break; }
            }
            firstScan = s.nextScan; s.started = false; s.list = 0;
        }
        if (found) { out = best; if (bestEvent.type) Flag(bestEvent); return true; }
        return false;
    }
};
